-- Real existing principals; all changes roll back via the evidence exception.
DO $t$
#variable_conflict use_column
DECLARE p uuid:='e4f51cd6-fb25-475e-980a-5e46070d678f';
 pe uuid:='565152cc-961b-4974-80b2-93ebd156ec46'; se uuid:='47f183de-2809-4c9d-91b0-ab323ff3d0ad';
 t uuid; added uuid; b uuid; h uuid; n int; v int; code text; ev text:=''; old_date date; j jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM schedule_baselines WHERE project_id=p) THEN RAISE EXCEPTION 'Test project already baselined'; END IF;
 INSERT INTO project_team_members(project_id,profile_id,role,access_level)
 SELECT p,id,'sched1b_test','write' FROM profiles WHERE auth_user_id IN (pe,se);
 PERFORM set_config('request.jwt.claim.sub',pe::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',pe,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 IF NOT can_edit_schedule(auth.uid()) THEN RAISE EXCEPTION 'Wrong planning principal'; END IF;
 INSERT INTO project_tasks(project_id,task_id_in_schedule,task_name) VALUES(p,'SCHED1B-DELETE','Draft deletion test') RETURNING id INTO t;
 DELETE FROM project_tasks WHERE id=t; GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION '(a) draft deletion failed'; END IF;
 INSERT INTO project_tasks(project_id,task_id_in_schedule,task_name,planned_start_date) VALUES(p,'SCHED1B-REMOVE','Removal test','2026-11-28') RETURNING id,planned_start_date INTO t,old_date;
 ev:=ev||E'\n(a) planning_engineer draft INSERT + DELETE: passed';
 v:=publish_schedule_baseline(p,NULL);
 IF v<>1 THEN RAISE EXCEPTION '(b) version 1 missing'; END IF;
 code:='allowed'; BEGIN INSERT INTO project_tasks(project_id,task_id_in_schedule,task_name) VALUES(p,'SCHED1B-DIRECT','Direct test'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(b) direct INSERT: %',code; END IF;
 code:='allowed'; BEGIN PERFORM schedule_add_task(p,'{"task_id_in_schedule":"SCHED1B-ADD","task_name":"Added task"}',' '); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'22023' THEN RAISE EXCEPTION '(b) add reason: %',code; END IF;
 added:=schedule_add_task(p,'{"task_id_in_schedule":"SCHED1B-ADD","task_name":"Added task","duration_days":3,"planned_start_date":"2026-11-28"}','Client approved extra work');
 IF (SELECT baseline_version FROM project_tasks WHERE id=added) IS NOT NULL THEN RAISE EXCEPTION '(b) added task not pending'; END IF;
 code:='allowed'; BEGIN DELETE FROM project_tasks WHERE id=t; EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(b) direct DELETE: %',code; END IF;
 code:='allowed'; BEGIN PERFORM schedule_remove_task(t,' '); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'22023' THEN RAISE EXCEPTION '(b) remove reason: %',code; END IF;
 INSERT INTO schedule_task_comments(project_id,task_id,body) VALUES(p,t,'Preserve this history');
 PERFORM schedule_remove_task(t,'Scope withdrawn by client');
 IF NOT EXISTS(SELECT 1 FROM project_tasks WHERE id=t AND is_removed AND removed_by=pe AND removed_reason='Scope withdrawn by client' AND removed_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM schedule_task_comments WHERE task_id=t) THEN RAISE EXCEPTION '(b) archive/history missing'; END IF;
 IF (SELECT count(*) FROM schedule_audit_log WHERE task_id IN (t,added) AND action IN ('add','remove') AND actor_id=pe AND length(reason)>0)<>2 THEN RAISE EXCEPTION '(b) audits missing'; END IF;
 code:='allowed'; BEGIN UPDATE project_tasks SET duration_days=9 WHERE id=added; EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(b) pending task direct edit: %',code; END IF;
 PERFORM set_config('hstack.schedule_membership','add',true);
 code:='allowed'; BEGIN INSERT INTO project_tasks(project_id,task_id_in_schedule,task_name) VALUES(p,'SCHED1B-SPOOF','Spoof context'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(b) context spoof: %',code; END IF;
 PERFORM set_config('hstack.schedule_membership','',true);
 ev:=ev||E'\n(b) direct INSERT/DELETE 42501; blank add/remove reasons 22023; reasoned add pending; removal retains row/comment/audit; pending direct edit and context spoof 42501';
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',se::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',se,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 IF can_edit_schedule(auth.uid()) THEN RAISE EXCEPTION 'Site principal is editor'; END IF;
 code:='allowed'; BEGIN PERFORM schedule_add_task(p,'{"task_id_in_schedule":"SCHED1B-SITE","task_name":"Site insert"}','Site test'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(c) site add: %',code; END IF;
 code:='allowed'; BEGIN PERFORM schedule_remove_task(added,'Site test'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(c) site remove: %',code; END IF;
 ev:=ev||E'\n(c) site_engineer add/remove: 42501';
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',pe::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',pe,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 code:='allowed'; BEGIN INSERT INTO schedule_holidays(holiday_date,label) VALUES('2099-11-30','SCHED1b holiday'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(d) direct holiday: %',code; END IF;
 code:='allowed'; BEGIN PERFORM schedule_change_holiday('2099-11-30','SCHED1b holiday',true,' '); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'22023' THEN RAISE EXCEPTION '(d) holiday reason: %',code; END IF;
 PERFORM schedule_change_holiday('2099-11-30','SCHED1b holiday',true,'Calendar approved');
 code:='allowed'; BEGIN UPDATE schedule_holidays SET is_active=false WHERE holiday_date='2099-11-30'; EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(d) direct holiday toggle: %',code; END IF;
 PERFORM schedule_change_holiday('2099-11-30','SCHED1b holiday',false,'Holiday cancelled');
 IF (SELECT planned_start_date FROM project_tasks WHERE id=t) IS DISTINCT FROM old_date THEN RAISE EXCEPTION '(d) stored date moved'; END IF;
 ev:=ev||E'\n(d) direct holiday INSERT/toggle 42501; blank reason 22023; checked changes audited; stored planned_start_date unchanged';
 RESET ROLE;
 INSERT INTO panel_batches(project_id,bay_number,total_panels,completed_panels,current_stage,status) VALUES(p,103,4,4,'ready','in_progress') RETURNING id INTO b;
 PERFORM set_config('request.jwt.claim.sub',se::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',se,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 IF NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND role='factory_supervisor') THEN RAISE EXCEPTION 'Wrong factory supervisor principal'; END IF;
 code:='allowed'; BEGIN PERFORM create_panel_handover_task(b); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(e) confirmed helper restriction: %',code; END IF;
 code:='allowed'; BEGIN INSERT INTO project_tasks(project_id,task_id_in_schedule,task_name) VALUES(p,'SCHED1B-FACTORY','Arbitrary supervisor task'); EXCEPTION WHEN OTHERS THEN code:=SQLSTATE; END;
 IF code<>'42501' THEN RAISE EXCEPTION '(e) arbitrary task insert: %',code; END IF;
 ev:=ev||E'\n(e) factory_supervisor helper and arbitrary INSERT: 42501 (confirmed existing restriction)';
 RESET ROLE;
 IF (SELECT count(*) FROM schedule_library_activities)<>15 OR (SELECT count(*) FROM schedule_library_tasks)<>107 THEN RAISE EXCEPTION '(f) library counts'; END IF;
 IF EXISTS(SELECT code FROM schedule_library_tasks GROUP BY code HAVING count(*)>1) OR EXISTS(SELECT code FROM schedule_library_activities GROUP BY code HAVING count(*)>1) THEN RAISE EXCEPTION '(f) duplicate codes'; END IF;
 IF (SELECT phase FROM schedule_library_activities WHERE code='13')<>'site' OR EXISTS(SELECT 1 FROM schedule_library_activities WHERE code<>'13' AND phase<>'factory') OR EXISTS(SELECT 1 FROM schedule_library_tasks t JOIN schedule_library_activities a ON a.id=t.activity_id WHERE a.code IN ('14','15') AND t.std_start_day IS NOT NULL) THEN RAISE EXCEPTION '(f) phase/null days'; END IF;
 ev:=ev||E'\n(f) 15 activities, 107 tasks; no duplicate codes; site/factory phases and null extra-work days correct';
 PERFORM set_config('request.jwt.claim.sub',pe::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',pe,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 v:=publish_schedule_baseline(p,'Revision with scope add/removal');
 SELECT snapshot INTO j FROM schedule_baselines WHERE project_id=p AND version=v;
 IF v<>2 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j) e WHERE e->>'id'=added::text AND (e->>'is_removed')::boolean=false AND (e->>'baseline_version')::int=2) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j) e WHERE e->>'id'=t::text AND (e->>'is_removed')::boolean=true AND e->>'removed_reason'='Scope withdrawn by client') OR (SELECT baseline_version FROM project_tasks WHERE id=added)<>2 THEN RAISE EXCEPTION '(g) revision snapshot'; END IF;
 ev:=ev||E'\n(g) version 2 includes added task, marks removal with reason/actor/time; new baseline_version=2';
 RESET ROLE;
 RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SCHED1B ROLLBACK EVIDENCE'||ev;
END $t$;
